sealed class NdrException: kotlin.Exception() {

    class InvalidKey(

        val v1: kotlin.String
        ) : NdrException() {
        override val message
            get() = "v1=${ v1 }"
    }

    class InvalidEvent(

        val v1: kotlin.String
        ) : NdrException() {
        override val message
            get() = "v1=${ v1 }"
    }

    class CryptoFailure(

        val v1: kotlin.String
        ) : NdrException() {
        override val message
            get() = "v1=${ v1 }"
    }

    class StateMismatch(

        val v1: kotlin.String
        ) : NdrException() {
        override val message
            get() = "v1=${ v1 }"
    }

    class Serialization(

        val v1: kotlin.String
        ) : NdrException() {
        override val message
            get() = "v1=${ v1 }"
    }

    class InviteException(

        val v1: kotlin.String
        ) : NdrException() {
        override val message
            get() = "v1=${ v1 }"
    }

    class SessionNotReady(

        val v1: kotlin.String
        ) : NdrException() {
        override val message
            get() = "v1=${ v1 }"
    }


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<NdrException> {
        override fun lift(error_buf: RustBuffer.ByValue): NdrException = FfiConverterTypeNdrError.lift(error_buf)
    }


}

/**
 * @suppress
 */
public object FfiConverterTypeNdrError : FfiConverterRustBuffer<NdrException> {
    override fun read(buf: ByteBuffer): NdrException {


        return when(buf.getInt()) {
            1 -> NdrException.InvalidKey(
                FfiConverterString.read(buf),
                )
            2 -> NdrException.InvalidEvent(
                FfiConverterString.read(buf),
                )
            3 -> NdrException.CryptoFailure(
                FfiConverterString.read(buf),
                )
            4 -> NdrException.StateMismatch(
                FfiConverterString.read(buf),
                )
            5 -> NdrException.Serialization(
                FfiConverterString.read(buf),
                )
            6 -> NdrException.InviteException(
                FfiConverterString.read(buf),
                )
            7 -> NdrException.SessionNotReady(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: NdrException): ULong {
        return when(value) {
            is NdrException.InvalidKey -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is NdrException.InvalidEvent -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is NdrException.CryptoFailure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is NdrException.StateMismatch -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is NdrException.Serialization -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is NdrException.InviteException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is NdrException.SessionNotReady -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: NdrException, buf: ByteBuffer) {
        when(value) {
            is NdrException.InvalidKey -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is NdrException.InvalidEvent -> {
                buf.putInt(2)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is NdrException.CryptoFailure -> {
                buf.putInt(3)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is NdrException.StateMismatch -> {
                buf.putInt(4)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is NdrException.Serialization -> {
                buf.putInt(5)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is NdrException.InviteException -> {
                buf.putInt(6)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is NdrException.SessionNotReady -> {
                buf.putInt(7)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




